    Assertions.assertNotEquals(creds1, creds2);
    Assertions.assertEquals(creds1, creds3);
}

@Test
public void testNTCredentialsHashCode() {
    final NTCredentials creds1 = new NTCredentials("name", "pwd".toCharArray(), "somehost", "domain");
    final NTCredentials creds2 = new NTCredentials("othername", "pwd".toCharArray(), "somehost", "domain");
    final NTCredentials creds3 = new NTCredentials("name", "otherpwd".toCharArray(), "SomeHost", "Domain");
    final NTCredentials creds4 = new NTCredentials("name", "pwd".toCharArray(), "otherhost", "domain");
    final NTCredentials creds5 = new NTCredentials("name", "pwd".toCharArray(), null, "domain");
    final NTCredentials creds6 = new NTCredentials("name", "pwd".toCharArray(), "somehost", "ms");
    final NTCredentials creds7 = new NTCredentials("name", "pwd".toCharArray(), "somehost", null);
    final NTCredentials creds8 = new NTCredentials("name", "pwd".toCharArray(), null, "domain");
    final NTCredentials creds9 = new NTCredentials("name", "pwd".toCharArray(), "somehost", null);
    Assertions.assertTrue(creds1.hashCode() == creds1.hashCode());
    Assertions.assertTrue(creds1.hashCode() != creds2.hashCode());
    Assertions.assertEquals(creds1.hashCode(), creds3.hashCode());
    Assertions.assertNotEquals(creds1.hashCode(), creds4.hashCode());
    Assertions.assertNotEquals(creds1.hashCode(), creds5.hashCode());
    Assertions.assertNotEquals(creds1.hashCode(), creds6.hashCode());
    Assertions.assertNotEquals(creds1.hashCode(), creds7.hashCode());
    Assertions.assertEquals(creds8.hashCode(), creds5.hashCode());
    Assertions.assertEquals(creds9.hashCode(), creds7.hashCode());
}

@Test
public void testNTCredentialsEquals() {
