@Test
public void testMultipartWriteTo() throws Exception {
    final String helloWorld = "hello world";
    final List<NameValuePair> parameters = new ArrayList<>();
    parameters.add(new BasicNameValuePair(MimeConsts.FIELD_PARAM_NAME, "test"));
    parameters.add(new BasicNameValuePair(MimeConsts.FIELD_PARAM_FILENAME, helloWorld));
    final MultipartFormEntity entity = MultipartEntityBuilder.create().setStrictMode().setBoundary("xxxxxxxxxxxxxxxxxxxxxxxx").addPart(new FormBodyPartBuilder().setName("test").setBody(new StringBody("hello world", ContentType.TEXT_PLAIN)).addField("Content-Disposition", "multipart/form-data", parameters).build()).buildEntity();
    final ByteArrayOutputStream out = new ByteArrayOutputStream();
    entity.writeTo(out);
    out.close();
    Assertions.assertEquals("--xxxxxxxxxxxxxxxxxxxxxxxx\r\n" + "Content-Disposition: multipart/form-data; name=\"test\"; filename=\"hello world\"\r\n" + "Content-Type: text/plain; charset=ISO-8859-1\r\n" + "\r\n" + helloWorld + "\r\n" + "--xxxxxxxxxxxxxxxxxxxxxxxx--\r\n", out.toString(StandardCharsets.US_ASCII.name()));
}

