@Test
public void testMultipartFormStringPartsMultiCharsets() throws Exception {
    final String s1 = constructString(SWISS_GERMAN_HELLO);
    final String s2 = constructString(RUSSIAN_HELLO);
    final FormBodyPart p1 = FormBodyPartBuilder.create("field1", new StringBody(s1, ContentType.create("text/plain", StandardCharsets.ISO_8859_1))).build();
    final FormBodyPart p2 = FormBodyPartBuilder.create("field2", new StringBody(s2, ContentType.create("text/plain", Charset.forName("KOI8-R")))).build();
    final HttpStrictMultipart multipart = new HttpStrictMultipart(null, "foo", Arrays.asList(p1, p2));
    final ByteArrayOutputStream out1 = new ByteArrayOutputStream();
    multipart.writeTo(out1);
    out1.close();
    final ByteArrayOutputStream out2 = new ByteArrayOutputStream();
    out2.write(("--foo\r\n" + "Content-Disposition: form-data; name=\"field1\"\r\n" + "Content-Type: text/plain; charset=ISO-8859-1\r\n" + "\r\n").getBytes(StandardCharsets.US_ASCII));
    out2.write(s1.getBytes(StandardCharsets.ISO_8859_1));
    out2.write(("\r\n" + "--foo\r\n" + "Content-Disposition: form-data; name=\"field2\"\r\n" + "Content-Type: text/plain; charset=KOI8-R\r\n" + "\r\n").getBytes(StandardCharsets.US_ASCII));
    out2.write(s2.getBytes(Charset.forName("KOI8-R")));
    out2.write(("\r\n" + "--foo--\r\n").getBytes(StandardCharsets.US_ASCII));
    out2.close();
    final byte[] actual = out1.toByteArray();
    final byte[] expected = out2.toByteArray();
    Assertions.assertEquals(expected.length, actual.length);
    for (int i = 0; i < actual.length; i++) {
        Assertions.assertEquals(expected[i], actual[i]);
    }
    Assertions.assertEquals(expected.length, multipart.getTotalLength());
}

@Test
public void testExplictContractorParams() throws Exception {
    final HttpEntity entity = MultipartEntityBuilder.create().setLaxMode().setBoundary("whatever").setCharset(StandardCharsets.UTF_8).build();
    Assertions.assertNull(entity.getContentEncoding());
    final String contentType = entity.getContentType();
    final HeaderElement elem = BasicHeaderValueParser.INSTANCE.parseHeaderElement(contentType, new ParserCursor(0, contentType.length()));
    Assertions.assertEquals("multipart/mixed", elem.getName());
    final NameValuePair p1 = elem.getParameterByName("boundary");
    Assertions.assertNotNull(p1);
    Assertions.assertEquals("whatever", p1.getValue());
    final NameValuePair p2 = elem.getParameterByName("charset");
    Assertions.assertNotNull(p2);
    Assertions.assertEquals("UTF-8", p2.getValue());
}

@Test
public void testImplictContractorParams() throws Exception {
    final HttpEntity entity = MultipartEntityBuilder.create().build();
    Assertions.assertNull(entity.getContentEncoding());
    final String contentType = entity.getContentType();
    final HeaderElement elem = BasicHeaderValueParser.INSTANCE.parseHeaderElement(contentType, new ParserCursor(0, contentType.length()));
    Assertions.assertEquals("multipart/mixed", elem.getName());
    final NameValuePair p1 = elem.getParameterByName("boundary");
    Assertions.assertNotNull(p1);
    final String boundary = p1.getValue();
    Assertions.assertNotNull(boundary);
    Assertions.assertTrue(boundary.length() >= 30);
    Assertions.assertTrue(boundary.length() <= 40);
    final NameValuePair p2 = elem.getParameterByName("charset");
    Assertions.assertNull(p2);
}

@Test
public void testRepeatable() throws Exception {
    final HttpEntity entity = MultipartEntityBuilder.create().addTextBody("p1", "blah blah", ContentType.DEFAULT_TEXT).addTextBody("p2", "yada yada", ContentType.DEFAULT_TEXT).build();
    Assertions.assertTrue(entity.isRepeatable());
    Assertions.assertFalse(entity.isChunked());
    Assertions.assertFalse(entity.isStreaming());
    final long len = entity.getContentLength();
    Assertions.assertEquals(len, entity.getContentLength());
    ByteArrayOutputStream out = new ByteArrayOutputStream();
    entity.writeTo(out);
    out.close();
    byte[] bytes = out.toByteArray();
    Assertions.assertNotNull(bytes);
    Assertions.assertEquals(bytes.length, len);
    Assertions.assertEquals(len, entity.getContentLength());
    out = new ByteArrayOutputStream();
    entity.writeTo(out);
    out.close();
    bytes = out.toByteArray();
    Assertions.assertNotNull(bytes);
    Assertions.assertEquals(bytes.length, len);
}

@Test
public void testNonRepeatable() throws Exception {
    final HttpEntity entity = MultipartEntityBuilder.create().addPart("p1", new InputStreamBody(new ByteArrayInputStream("blah blah".getBytes()), ContentType.DEFAULT_BINARY)).addPart("p2", new InputStreamBody(new ByteArrayInputStream("yada yada".getBytes()), ContentType.DEFAULT_BINARY)).build();
    Assertions.assertFalse(entity.isRepeatable());
    Assertions.assertTrue(entity.isChunked());
    Assertions.assertTrue(entity.isStreaming());
    Assertions.assertEquals(-1, entity.getContentLength());
}

