    final MultipartPart p1 = MultipartPartBuilder.create(new StringBody(s1, ContentType.create("text/plain", StandardCharsets.ISO_8859_1))).build();
    final MultipartPart p2 = MultipartPartBuilder.create(new StringBody(s2, ContentType.create("text/plain", Charset.forName("KOI8-R")))).build();
