/**
 * Test digest authentication using the MD5-sess algorithm.
 */
@Test
public void testDigestAuthenticationMD5Sess() throws Exception {
    // Example using Digest auth with MD5-sess
    final String realm = "realm";
    final String username = "username";
    final String password = "password";
    final String nonce = "e273f1776275974f1a120d8b92c5b3cb";
    final HttpRequest request = new BasicHttpRequest("Simple", "/");
    final HttpHost host = new HttpHost("somehost", 80);
    final CredentialsProvider credentialsProvider = CredentialsProviderBuilder.create().add(new AuthScope(host, realm, null), username, password.toCharArray()).build();
    final String challenge = StandardAuthScheme.DIGEST + " realm=\"" + realm + "\", " + "nonce=\"" + nonce + "\", " + "opaque=\"SomeString\", " + "stale=false, " + "algorithm=MD5-sess, " + // we pass both but expect auth to be used
    "qop=\"auth,auth-int\"";
    final AuthChallenge authChallenge = parse(challenge);
    final DigestScheme authscheme = new DigestScheme();
    authscheme.processChallenge(authChallenge, null);
    Assertions.assertTrue(authscheme.isResponseReady(host, credentialsProvider, null));
    final String authResponse = authscheme.generateAuthResponse(host, request, null);
    // test for quotes
    Assertions.assertTrue(authResponse.indexOf("nc=00000001") > 0);
    // test for quotes
