        @Override
        public HttpServerRequestHandler decorate(final HttpServerRequestHandler requestHandler) {
            return new RedirectingDecorator(requestHandler, new OldPathRedirectResolver("/oldlocation", "/random", HttpStatus.SC_MOVED_TEMPORARILY)) {

